<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, errorMessage } from '../services/api'
import { useFeedbackStore } from '../stores/feedback'
const now=new Date();const filters=reactive({year:now.getFullYear(),month:now.getMonth()+1});const data=ref(null);const feedback=useFeedbackStore();const money=v=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(Number(v||0))
async function load(){try{data.value=(await api.get('/admin/statistics',{params:filters})).data}catch(e){feedback.show(errorMessage(e),'error')}}onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1>Estatísticas</h1><p>Desempenho das encomendas confirmadas.</p></div><v-btn :href="`/admin/estatisticas/export.xlsx?year=${filters.year}&month=${filters.month}`" prepend-icon="mdi-microsoft-excel" color="success">Exportar Excel</v-btn></div><v-card class="soft-card pa-4 mb-6"><v-row dense><v-col cols="6" md="3"><v-text-field v-model.number="filters.year" type="number" hide-details label="Ano"/></v-col><v-col cols="6" md="3"><v-select v-model="filters.month" hide-details label="Mês" :items="Array.from({length:12},(_,i)=>({title:new Date(2020,i).toLocaleString('pt-PT',{month:'long'}),value:i+1}))"/></v-col><v-col cols="12" md="3"><v-btn block height="48" color="primary" @click="load">Atualizar</v-btn></v-col></v-row></v-card><template v-if="data"><v-row><v-col v-for="item in [['Vendas confirmadas',money(data.report.confirmed_revenue)],['Unidades',data.report.confirmed_units],['Confirmadas',data.report.confirmed_orders],['Pendentes',data.report.pending_orders]]" :key="item[0]" cols="6" md="3"><v-card class="metric soft-card"><div class="metric-label">{{item[0]}}</div><div class="metric-value">{{item[1]}}</div></v-card></v-col></v-row><v-card class="soft-card mt-6"><v-card-title class="pa-5">Últimos 12 meses</v-card-title><v-table><thead><tr><th>Período</th><th>Confirmadas</th><th>Unidades</th><th class="text-right">Vendas</th></tr></thead><tbody><tr v-for="row in data.series" :key="`${row.year}-${row.month}`"><td>{{String(row.month).padStart(2,'0')}}/{{row.year}}</td><td>{{row.confirmed_orders}}</td><td>{{row.confirmed_units}}</td><td class="text-right font-weight-bold">{{money(row.confirmed_revenue)}}</td></tr></tbody></v-table></v-card></template></div></template>
